=================== erc20-flash-mint.adoc
     1	= ERC-20 Flash Mint
     2	
     3	Extension of xref:erc20.adoc[ERC-20] that provides flash loan support at the token level.
     4	
     5	[[usage]]
     6	== Usage
     7	
     8	In order to make https://docs.rs/openzeppelin-stylus/0.3.0/openzeppelin_stylus/token/erc20/extensions/flash_mint/index.html[`ERC-20 Flash Mint`]  methods “external” so that other contracts can call them, you need to add the following code to your contract:
     9	
    10	[source,rust]
    11	----
    12	use openzeppelin_stylus::token::erc20::{
    13	    extensions::{flash_mint, Erc20FlashMint, IErc3156FlashLender},
    14	    Erc20, IErc20,
    15	};
    16	
    17	#[entrypoint]
    18	#[storage]
    19	struct Erc20FlashMintExample {
    20	    erc20: Erc20,
    21	    flash_mint: Erc20FlashMint,
    22	}
    23	
    24	#[public]
    25	#[implements(IErc20<Error = flash_mint::Error>, IErc3156FlashLender<Error = flash_mint::Error>)]
    26	impl Erc20FlashMintExample {}
    27	
    28	#[public]
    29	impl IErc3156FlashLender for Erc20FlashMintExample {
    30	    type Error = flash_mint::Error;
    31	
    32	    fn max_flash_loan(&self, token: Address) -> U256 {
    33	        self.flash_mint.max_flash_loan(token, &self.erc20)
    34	    }
    35	
    36	    fn flash_fee(
    37	        &self,
    38	        token: Address,
    39	        value: U256,
    40	    ) -> Result<U256, Self::Error> {
    41	        self.flash_mint.flash_fee(token, value)
    42	    }
    43	
    44	    fn flash_loan(
    45	        &mut self,
    46	        receiver: Address,
    47	        token: Address,
    48	        value: U256,
    49	        data: Bytes,
    50	    ) -> Result<bool, Self::Error> {
    51	        self.flash_mint.flash_loan(
    52	            receiver,
    53	            token,
    54	            value,
    55	            &data,
    56	            &mut self.erc20,
    57	        )
    58	    }
    59	}
    60	
    61	#[public]
    62	impl IErc20 for Erc20FlashMintExample {
    63	    type Error = flash_mint::Error;
    64	
    65	    fn total_supply(&self) -> U256 {
    66	        self.erc20.total_supply()
    67	    }
    68	
    69	    fn balance_of(&self, account: Address) -> U256 {
    70	        self.erc20.balance_of(account)
    71	    }
    72	
    73	    fn transfer(
    74	        &mut self,
    75	        to: Address,
    76	        value: U256,
    77	    ) -> Result<bool, Self::Error> {
    78	        Ok(self.erc20.transfer(to, value)?)
    79	    }
    80	
    81	    fn allowance(&self, owner: Address, spender: Address) -> U256 {
    82	        self.erc20.allowance(owner, spender)
    83	    }
    84	
    85	    fn approve(
    86	        &mut self,
    87	        spender: Address,
    88	        value: U256,
    89	    ) -> Result<bool, Self::Error> {
    90	        Ok(self.erc20.approve(spender, value)?)
    91	    }
    92	
    93	    fn transfer_from(
    94	        &mut self,
    95	        from: Address,
    96	        to: Address,
    97	        value: U256,
    98	    ) -> Result<bool, Self::Error> {
    99	        Ok(self.erc20.transfer_from(from, to, value)?)
   100	    }
   101	}
   102	----
=================== erc20-metadata.adoc
     1	= ERC-20 Metadata
     2	
     3	Extension of xref:erc20.adoc[ERC-20] that adds the optional metadata functions from the ERC20 standard.
     4	
     5	[[usage]]
     6	== Usage
     7	
     8	In order to make https://docs.rs/openzeppelin-stylus/0.3.0/openzeppelin_stylus/token/erc20/extensions/metadata/index.html[`ERC-20 Metadata`]  methods “external” so that other contracts can call them, you need to add the following code to your contract:
     9	
    10	[source,rust]
    11	----
    12	use openzeppelin_stylus::{
    13	    token::erc20::{
    14	        self,
    15	        extensions::{Erc20Metadata, IErc20Metadata},
    16	        Erc20, IErc20,
    17	    },
    18	};
    19	
    20	#[entrypoint]
    21	#[storage]
    22	struct Erc20Example {
    23	    erc20: Erc20,
    24	    metadata: Erc20Metadata,
    25	}
    26	
    27	#[public]
    28	#[implements(IErc20<Error = erc20::Error>, IErc20Metadata, IErc165)]
    29	impl Erc20Example {
    30	    #[constructor]
    31	    fn constructor(&mut self, name: String, symbol: String) {
    32	        self.metadata.constructor(name, symbol);
    33	    }
    34	
    35	    // ...
    36	}
    37	
    38	#[public]
    39	impl IErc20 for Erc20Example {
    40	    type Error = erc20::Error;
    41	
    42	    fn total_supply(&self) -> U256 {
    43	        self.erc20.total_supply()
    44	    }
    45	
    46	    fn balance_of(&self, account: Address) -> U256 {
    47	        self.erc20.balance_of(account)
    48	    }
    49	
    50	    fn transfer(
    51	        &mut self,
    52	        to: Address,
    53	        value: U256,
    54	    ) -> Result<bool, Self::Error> {
    55	        self.erc20.transfer(to, value)
    56	    }
    57	
    58	    fn allowance(&self, owner: Address, spender: Address) -> U256 {
    59	        self.erc20.allowance(owner, spender)
    60	    }
    61	
    62	    fn approve(
    63	        &mut self,
    64	        spender: Address,
    65	        value: U256,
    66	    ) -> Result<bool, Self::Error> {
    67	        self.erc20.approve(spender, value)
    68	    }
    69	
    70	    fn transfer_from(
    71	        &mut self,
    72	        from: Address,
    73	        to: Address,
    74	        value: U256,
    75	    ) -> Result<bool, Self::Error> {
    76	        self.erc20.transfer_from(from, to, value)
    77	    }
    78	}
    79	
    80	#[public]
    81	impl IErc20Metadata for Erc20Example {
    82	    fn name(&self) -> String {
    83	        self.metadata.name()
    84	    }
    85	
    86	    fn symbol(&self) -> String {
    87	        self.metadata.symbol()
    88	    }
    89	
    90	    fn decimals(&self) -> U8 {
    91	        self.metadata.decimals()
    92	    }
    93	}
    94	
    95	#[public]
    96	impl IErc165 for Erc20Example {
    97	    fn supports_interface(&self, interface_id: B32) -> bool {
    98	        self.erc20.supports_interface(interface_id)
    99	            || self.metadata.supports_interface(interface_id)
   100	    }
   101	}
