=================== erc20-pausable.adoc
     1	= ERC-20 Pausable
     2	
     3	ERC20 token with pausable token transfers, minting, and burning.
     4	
     5	Useful for scenarios such as preventing trades until the end of an evaluation period, or having an emergency switch for freezing all token transfers in the event of a large bug.
     6	
     7	[[usage]]
     8	== Usage
     9	
    10	In order to make your ERC20 token `pausable`, you need to use the https://docs.rs/openzeppelin-stylus/0.3.0/openzeppelin_stylus/utils/pausable/index.html[`Pausable`] contract and apply its mechanisms to ERC20 token functions as follows:
    11	
    12	[source,rust]
    13	----
    14	use openzeppelin_stylus::{
    15	    token::erc20::{self, Erc20, IErc20},
    16	    utils::{pausable, IPausable, Pausable},
    17	};
    18	
    19	#[derive(SolidityError, Debug)]
    20	enum Error {
    21	    InsufficientBalance(erc20::ERC20InsufficientBalance),
    22	    InvalidSender(erc20::ERC20InvalidSender),
    23	    InvalidReceiver(erc20::ERC20InvalidReceiver),
    24	    InsufficientAllowance(erc20::ERC20InsufficientAllowance),
    25	    InvalidSpender(erc20::ERC20InvalidSpender),
    26	    InvalidApprover(erc20::ERC20InvalidApprover),
    27	    EnforcedPause(pausable::EnforcedPause),
    28	    ExpectedPause(pausable::ExpectedPause),
    29	}
    30	
    31	impl From<erc20::Error> for Error {
    32	    fn from(value: erc20::Error) -> Self {
    33	        match value {
    34	            erc20::Error::InsufficientBalance(e) => {
    35	                Error::InsufficientBalance(e)
    36	            }
    37	            erc20::Error::InvalidSender(e) => Error::InvalidSender(e),
    38	            erc20::Error::InvalidReceiver(e) => Error::InvalidReceiver(e),
    39	            erc20::Error::InsufficientAllowance(e) => {
    40	                Error::InsufficientAllowance(e)
    41	            }
    42	            erc20::Error::InvalidSpender(e) => Error::InvalidSpender(e),
    43	            erc20::Error::InvalidApprover(e) => Error::InvalidApprover(e),
    44	        }
    45	    }
    46	}
    47	
    48	impl From<pausable::Error> for Error {
    49	    fn from(value: pausable::Error) -> Self {
    50	        match value {
    51	            pausable::Error::EnforcedPause(e) => Error::EnforcedPause(e),
    52	            pausable::Error::ExpectedPause(e) => Error::ExpectedPause(e),
    53	        }
    54	    }
    55	}
