=================== erc721-consecutive.adoc
     1	= ERC-721 Consecutive
     2	
     3	Consecutive extension for xref:erc721.adoc[ERC-721] is useful for efficiently minting multiple tokens in a single transaction. This can significantly reduce gas costs and improve performance when creating a large number of tokens at once.
     4	
     5	[[usage]]
     6	== Usage
     7	
     8	In order to make https://docs.rs/openzeppelin-stylus/0.3.0/openzeppelin_stylus/token/erc721/extensions/consecutive/index.html[`ERC-721 Consecutive`] methods “external” so that other contracts can call them, you need to add the following code to your contract:
     9	
    10	[source,rust]
    11	----
    12	use openzeppelin_stylus::{
    13	    token::erc721::{
    14	        extensions::{consecutive, Erc721Consecutive},
    15	        Erc721, IErc721,
    16	    },
    17	    utils::introspection::erc165::IErc165,
    18	};
    19	
    20	#[entrypoint]
    21	#[storage]
    22	struct Erc721ConsecutiveExample {
    23	    erc721_consecutive: Erc721Consecutive,
    24	}
    25	
    26	#[public]
    27	#[inherit(IErc721<Error = consecutive::Error>, IErc165)]
    28	impl Erc721ConsecutiveExample {
    29	    #[constructor]
    30	    fn constructor(
    31	        &mut self,
    32	        receivers: Vec<Address>,
    33	        amounts: Vec<U96>,
    34	        first_consecutive_id: U96,
    35	        max_batch_size: U96,
    36	    ) -> Result<(), consecutive::Error> {
    37	        self.erc721_consecutive.first_consecutive_id.set(first_consecutive_id);
    38	        self.erc721_consecutive.max_batch_size.set(max_batch_size);
    39	        for (&receiver, &amount) in receivers.iter().zip(amounts.iter()) {
    40	            self.erc721_consecutive._mint_consecutive(receiver, amount)?;
    41	        }
    42	        Ok(())
    43	    }
    44	}
