=================== erc721-enumerable.adoc
     1	= ERC-721 Enumerable
     2	
     3	The OpenZeppelin xref:erc721.adoc[ERC-721] Enumerable extension is used to provide additional functionality to the standard ERC-721 token. Specifically, it allows for enumeration of all the token IDs in the contract as well as all the token IDs owned by each account. This is useful for applications that need to list or iterate over tokens, such as marketplaces or wallets.
     4	
     5	[[usage]]
     6	== Usage
     7	
     8	In order to make an xref:erc721.adoc[ERC-721] token with https://docs.rs/openzeppelin-stylus/0.3.0/openzeppelin_stylus/token/erc721/extensions/enumerable/index.html[Enumerable] flavour,
     9	you need to create a specified contract as follows:
    10	
    11	[source,rust]
    12	----
    13	use openzeppelin_stylus::{
    14	    token::erc721::{
    15	        self,
    16	        extensions::{enumerable, Erc721Enumerable, IErc721Burnable},
    17	        Erc721, IErc721,
    18	    },
    19	    utils::introspection::erc165::IErc165,
    20	};
    21	
    22	#[derive(SolidityError, Debug)]
    23	enum Error {
    24	    OutOfBoundsIndex(enumerable::ERC721OutOfBoundsIndex),
    25	    EnumerableForbiddenBatchMint(
    26	        enumerable::ERC721EnumerableForbiddenBatchMint,
    27	    ),
    28	    InvalidOwner(erc721::ERC721InvalidOwner),
    29	    NonexistentToken(erc721::ERC721NonexistentToken),
    30	    IncorrectOwner(erc721::ERC721IncorrectOwner),
    31	    InvalidSender(erc721::ERC721InvalidSender),
    32	    InvalidReceiver(erc721::ERC721InvalidReceiver),
    33	    InvalidReceiverWithReason(erc721::InvalidReceiverWithReason),
    34	    InsufficientApproval(erc721::ERC721InsufficientApproval),
    35	    InvalidApprover(erc721::ERC721InvalidApprover),
    36	    InvalidOperator(erc721::ERC721InvalidOperator),
    37	}
    38	
    39	impl From<enumerable::Error> for Error {
    40	    fn from(value: enumerable::Error) -> Self {
    41	        match value {
    42	            enumerable::Error::OutOfBoundsIndex(e) => {
    43	                Error::OutOfBoundsIndex(e)
    44	            }
    45	            enumerable::Error::EnumerableForbiddenBatchMint(e) => {
    46	                Error::EnumerableForbiddenBatchMint(e)
    47	            }
    48	        }
    49	    }
    50	}
    51	
    52	impl From<erc721::Error> for Error {
    53	    fn from(value: erc721::Error) -> Self {
    54	        match value {
    55	            erc721::Error::InvalidOwner(e) => Error::InvalidOwner(e),
    56	            erc721::Error::NonexistentToken(e) => Error::NonexistentToken(e),
    57	            erc721::Error::IncorrectOwner(e) => Error::IncorrectOwner(e),
    58	            erc721::Error::InvalidSender(e) => Error::InvalidSender(e),
    59	            erc721::Error::InvalidReceiver(e) => Error::InvalidReceiver(e),
    60	            erc721::Error::InvalidReceiverWithReason(e) => {
    61	                Error::InvalidReceiverWithReason(e)
    62	            }
    63	            erc721::Error::InsufficientApproval(e) => {
    64	                Error::InsufficientApproval(e)
    65	            }
    66	            erc721::Error::InvalidApprover(e) => Error::InvalidApprover(e),
    67	            erc721::Error::InvalidOperator(e) => Error::InvalidOperator(e),
    68	        }
    69	    }
    70	}
    71	
    72	#[entrypoint]
    73	#[storage]
    74	struct Erc721Example {
    75	    erc721: Erc721,
    76	    enumerable: Erc721Enumerable,
    77	}
