    83	        self.erc721._mint(to, token_id)?;
    84	
    85	        // Update the extension's state.
    86	        self.enumerable._add_token_to_all_tokens_enumeration(token_id);
    87	        self.enumerable._add_token_to_owner_enumeration(
    88	            to,
    89	            token_id,
    90	            &self.erc721,
    91	        )?;
    92	
    93	        Ok(())
    94	    }
    95	}
