=================== erc721-pausable.adoc
     1	= ERC-721 Pausable
     2	
     3	ERC721 token with pausable token transfers, minting, and burning.
     4	
     5	Useful for scenarios such as preventing trades until the end of an evaluation period, or having an emergency switch for freezing all token transfers, e.g. caused by a bug.
     6	
     7	[[usage]]
     8	== Usage
     9	
    10	In order to make your ERC721 token `pausable`, you need to use the https://docs.rs/openzeppelin-stylus/0.3.0/openzeppelin_stylus/utils/pausable/index.html[`Pausable`] contract and apply its mechanisms to ERC721 token functions as follows:
    11	
    12	[source,rust]
    13	----
    14	use openzeppelin_stylus::{
    15	    token::erc721::{self, Erc721, IErc721},
    16	    utils::{introspection::erc165::IErc165, pausable, IPausable, Pausable},
    17	};
    18	
    19	#[derive(SolidityError, Debug)]
    20	enum Error {
    21	    InvalidOwner(erc721::ERC721InvalidOwner),
    22	    NonexistentToken(erc721::ERC721NonexistentToken),
    23	    IncorrectOwner(erc721::ERC721IncorrectOwner),
    24	    InvalidSender(erc721::ERC721InvalidSender),
    25	    InvalidReceiver(erc721::ERC721InvalidReceiver),
    26	    InvalidReceiverWithReason(erc721::InvalidReceiverWithReason),
    27	    InsufficientApproval(erc721::ERC721InsufficientApproval),
    28	    InvalidApprover(erc721::ERC721InvalidApprover),
    29	    InvalidOperator(erc721::ERC721InvalidOperator),
    30	    EnforcedPause(pausable::EnforcedPause),
    31	    ExpectedPause(pausable::ExpectedPause),
    32	}
    33	
    34	impl From<erc721::Error> for Error {
    35	    fn from(value: erc721::Error) -> Self {
    36	        match value {
    37	            erc721::Error::InvalidOwner(e) => Error::InvalidOwner(e),
    38	            erc721::Error::NonexistentToken(e) => Error::NonexistentToken(e),
    39	            erc721::Error::IncorrectOwner(e) => Error::IncorrectOwner(e),
    40	            erc721::Error::InvalidSender(e) => Error::InvalidSender(e),
    41	            erc721::Error::InvalidReceiver(e) => Error::InvalidReceiver(e),
    42	            erc721::Error::InvalidReceiverWithReason(e) => {
    43	                Error::InvalidReceiverWithReason(e)
    44	            }
    45	            erc721::Error::InsufficientApproval(e) => {
    46	                Error::InsufficientApproval(e)
    47	            }
    48	            erc721::Error::InvalidApprover(e) => Error::InvalidApprover(e),
    49	            erc721::Error::InvalidOperator(e) => Error::InvalidOperator(e),
    50	        }
    51	    }
    52	}
    53	
    54	impl From<pausable::Error> for Error {
    55	    fn from(value: pausable::Error) -> Self {
    56	        match value {
    57	            pausable::Error::EnforcedPause(e) => Error::EnforcedPause(e),
    58	            pausable::Error::ExpectedPause(e) => Error::ExpectedPause(e),
    59	        }
    60	    }
    61	}
    62	
    63	#[entrypoint]
    64	#[storage]
    65	struct Erc721Example {
    66	    erc721: Erc721,
    67	    pausable: Pausable,
    68	}
    69	
    70	#[public]
    71	#[implements(IErc721<Error = Error>, IPausable, IErc165)]
    72	impl Erc721Example {
    73	    fn mint(&mut self, to: Address, token_id: U256) -> Result<(), Error> {
    74	        // ...
    75	        self.pausable.when_not_paused()?;
    76	        // ...
    77	        self.erc721._mint(to, token_id)?;
    78	        Ok(())
    79	    }
    80	}
