     1	= ERC-1155 Pausable
     2	
     3	xref:erc1155.adoc[ERC-1155] token with pausable token transfers, minting, and burning.
     4	
     5	Useful for scenarios such as preventing trades until the end of an evaluation period, or having an emergency switch for freezing all token transfers in the event of a large bug.
     6	
     7	[[usage]]
     8	== Usage
     9	
    10	In order to make your xref:erc1155.adoc[ERC-1155] token `pausable`, you need to use the https://docs.rs/openzeppelin-stylus/0.3.0/openzeppelin_stylus/utils/pausable/index.html[`Pausable`] contract and apply its mechanisms to ERC1155 token functions as follows:
    11	
    12	[source,rust]
    13	----
    14	use openzeppelin_stylus::{
    15	    token::erc1155::{self, Erc1155, IErc1155},
    16	    utils::{introspection::erc165::IErc165, pausable, IPausable, Pausable},
    17	};
    18	
    19	#[derive(SolidityError, Debug)]
    20	enum Error {
    21	    InsufficientBalance(erc1155::ERC1155InsufficientBalance),
    22	    InvalidSender(erc1155::ERC1155InvalidSender),
    23	    InvalidReceiver(erc1155::ERC1155InvalidReceiver),
    24	    InvalidReceiverWithReason(erc1155::InvalidReceiverWithReason),
    25	    MissingApprovalForAll(erc1155::ERC1155MissingApprovalForAll),
    26	    InvalidApprover(erc1155::ERC1155InvalidApprover),
    27	    InvalidOperator(erc1155::ERC1155InvalidOperator),
    28	    InvalidArrayLength(erc1155::ERC1155InvalidArrayLength),
    29	    EnforcedPause(pausable::EnforcedPause),
    30	    ExpectedPause(pausable::ExpectedPause),
    31	}
    32	
    33	impl From<erc1155::Error> for Error {
    34	    fn from(value: erc1155::Error) -> Self {
    35	        match value {
    36	            erc1155::Error::InsufficientBalance(e) => {
    37	                Error::InsufficientBalance(e)
    38	            }
    39	            erc1155::Error::InvalidSender(e) => Error::InvalidSender(e),
    40	            erc1155::Error::InvalidReceiver(e) => Error::InvalidReceiver(e),
    41	            erc1155::Error::InvalidReceiverWithReason(e) => {
